  const sx = x+wx, sy = y+wy;
  const src = [];
  for(let i=0;i<8;i++){
    const a=t*0.15*P[i%10]/P[(i+3)%10]+i*0.785;
    const r=50+35*Math.sin(t*0.08*P[(i+1)%10]/P[(i+2)%10]+i);
    src.push([240+Math.cos(a)*r*(1.1+i*0.08),120+Math.sin(a)*r*(0.65+i*0.04),0.035+0.008*P[i%10]/P[0],1.4+0.25*P[(i+4)%10]/P[0]]);
