  const fr=(px,py,pw,ph,s)=>(x>=px&&x<=px+pw&&y>=py&&y<=py+ph)?s:0;
  ui+=fr(8,8,464,1,0.9)+fr(8,8,1,224,0.9)+fr(8,232,464,1,0.9)+fr(472,8,1,224,0.9);
